io.on('connection', (socket) => {
  socket.on('join_board', async (boardId) => {
    const isMember = await BoardMember.findOne({ boardId, userId: socket.data.userId });
    if (!isMember) {
      return socket.emit('error', { message: 'Unauthorized access to project board' });
    }
    socket.join(`board:${boardId}`);
    socket.emit('joined_board_success', { boardId });
  });

  socket.on('move_card', async ({ boardId, cardId, newColumnId }) => {
    const isMember = await BoardMember.findOne({ boardId, userId: socket.data.userId });
    if (!isMember) return socket.emit('error', { message: 'Forbidden' });
    await CardModel.findByIdAndUpdate(cardId, { columnId: newColumnId });
    io.to(`board:${boardId}`).emit('card_moved', { cardId, newColumnId, movedBy: socket.data.userId });
  });
});
